SET LOCAL lock_timeout = '2s';
ALTER TABLE "public"."activity_review_template" DROP CONSTRAINT "activity_review_template_label_shape";
ALTER TABLE "public"."activity_review_template" ADD CONSTRAINT "activity_review_template_label_shape" CHECK (((btrim(label) <> ''::text) AND (char_length(label) <= 200))) NOT VALID;
ALTER TABLE "public"."app_user" DROP CONSTRAINT "app_user_greeting_name_length";
ALTER TABLE "public"."app_user" ADD CONSTRAINT "app_user_greeting_name_length" CHECK (((greeting_name IS NULL) OR ((char_length(greeting_name) >= 1) AND (char_length(greeting_name) <= 100)))) NOT VALID;
ALTER TABLE "public"."brief_item" ADD CONSTRAINT "brief_item_finding_length" CHECK (((finding IS NULL) OR (char_length(finding) <= 600))) NOT VALID;
ALTER TABLE "public"."brief_run" DROP CONSTRAINT "brief_run_narrative_length";
ALTER TABLE "public"."brief_run" ADD CONSTRAINT "brief_run_narrative_length" CHECK (((narrative IS NULL) OR (char_length(narrative) <= 600))) NOT VALID;
ALTER TABLE "public"."contact_confirm_submission" DROP CONSTRAINT "contact_confirm_submission_note_length";
ALTER TABLE "public"."contact_confirm_submission" ADD CONSTRAINT "contact_confirm_submission_note_length" CHECK (((note IS NULL) OR (char_length(note) <= 500))) NOT VALID;
ALTER TABLE "public"."deal_line_item" DROP CONSTRAINT "deal_line_item_bounded";
ALTER TABLE "public"."deal_line_item" ADD CONSTRAINT "deal_line_item_bounded" CHECK (((length(unit) <= 100) AND ((catalog_name IS NULL) OR (length(catalog_name) <= 500)) AND ((sku IS NULL) OR (length(sku) <= 200)))) NOT VALID;
ALTER TABLE "public"."deal_line_item" DROP CONSTRAINT "deal_line_item_description_present";
ALTER TABLE "public"."deal_line_item" ADD CONSTRAINT "deal_line_item_description_present" CHECK (((btrim(description) <> ''::text) AND (length(description) <= 2000))) NOT VALID;
ALTER TABLE "public"."legal_entity" DROP CONSTRAINT "legal_entity_imprint_bounded";
ALTER TABLE "public"."legal_entity" ADD CONSTRAINT "legal_entity_imprint_bounded" CHECK (((imprint IS NULL) OR (length(imprint) <= 4000))) NOT VALID;
ALTER TABLE "public"."legal_entity" DROP CONSTRAINT "legal_entity_offering_bounded";
ALTER TABLE "public"."legal_entity" ADD CONSTRAINT "legal_entity_offering_bounded" CHECK (((length(offer_summary) <= 4000) AND (length(icp) <= 4000) AND (length(value_proposition) <= 4000) AND (length(usp) <= 4000))) NOT VALID;
ALTER TABLE "public"."legal_entity" DROP CONSTRAINT "legal_entity_signature_template_bounded";
ALTER TABLE "public"."legal_entity" ADD CONSTRAINT "legal_entity_signature_template_bounded" CHECK (((signature_template IS NULL) OR (length(signature_template) <= 4000))) NOT VALID;
ALTER TABLE "public"."legal_review" ADD CONSTRAINT "legal_review_comments_bounded" CHECK (((comments IS NULL) OR (length(comments) <= 8000))) NOT VALID;
ALTER TABLE "public"."legal_review" ADD CONSTRAINT "legal_review_note_bounded" CHECK (((note IS NULL) OR (length(note) <= 4000))) NOT VALID;
ALTER TABLE "public"."notice" DROP CONSTRAINT "notice_content_bounded";
ALTER TABLE "public"."notice" ADD CONSTRAINT "notice_content_bounded" CHECK (((length(subject) <= 200) AND (length(body) <= 2000))) NOT VALID;
ALTER TABLE "public"."privacy_notice_case" DROP CONSTRAINT "privacy_notice_case_resolution_note_length";
ALTER TABLE "public"."privacy_notice_case" ADD CONSTRAINT "privacy_notice_case_resolution_note_length" CHECK (((resolution_note IS NULL) OR (char_length(resolution_note) <= 500))) NOT VALID;
ALTER TABLE "public"."product_translation" DROP CONSTRAINT "product_translation_bounded";
ALTER TABLE "public"."product_translation" ADD CONSTRAINT "product_translation_bounded" CHECK (((length(name) <= 500) AND ((description IS NULL) OR (length(description) <= 4000)))) NOT VALID;
ALTER TABLE "public"."project_health_assessment" ADD CONSTRAINT "project_health_note_bounded" CHECK (((note IS NULL) OR (length(note) <= 4000))) NOT VALID;
ALTER TABLE "public"."web_form" DROP CONSTRAINT "web_form_name_present";
ALTER TABLE "public"."web_form" ADD CONSTRAINT "web_form_name_present" CHECK (((length(btrim(name)) > 0) AND (length(name) <= 200))) NOT VALID;
ALTER TABLE "public"."weekly_review" DROP CONSTRAINT "weekly_review_narrative_length";
ALTER TABLE "public"."weekly_review" ADD CONSTRAINT "weekly_review_narrative_length" CHECK (((narrative IS NULL) OR (char_length(narrative) <= 600))) NOT VALID;
ALTER TABLE "public"."weekly_review_learning" DROP CONSTRAINT "weekly_review_learning_text_bound";
ALTER TABLE "public"."weekly_review_learning" ADD CONSTRAINT "weekly_review_learning_text_bound" CHECK ((length(text) <= 400)) NOT VALID;
